/// <summary>
/// MPJ_13564_AutoGeneratePaym
/// UI builder required for validating and list partameters at initialisation
/// </summary>
public class METVendAutoGeneratePaymUIBuilder extends SysOperationAutomaticUIBuilder
{
    DialogField paymMethod;
    container   conContainer;



}

Method.Source:
    /// <summary>
    /// MPJ_13564_AutoGeneratePaym
    /// Post build maps the dialog fields to contract
    /// </summary>
    public void postBuild()
    {
        super();

        // get references to dialog controls after creation
        paymMethod = this.bindInfo().getDialogField(this.dataContractObject(),
                                    methodStr(METVendAutoGeneratePaymContract, getPaymMethodList));
    }

    /// <summary>
    /// MPJ_13564_AutoGeneratePaym
    /// postRun allows validation and hiding of methods
    /// </summary>
    public void postRun()
    {
        //super();

        // register overrides for form control events
        paymMethod.registerOverrideMethod(methodstr(FormIntControl, lookup),
                methodstr(METVendAutoGeneratePaymUIBuilder, paymMethodLookup), this);

    }

    /// <summary>
    /// MPJ_13564_AutoGeneratePaym
    /// method of payment lookup
    /// </summary>
    /// <param name = "parmFormStringControl">dialog field</param>
    public void paymMethodLookup(FormStringControl parmFormStringControl)
    {
        Query                   query = new Query();
        QueryBuildDataSource    tableQBDS;

        tableQBDS = query.addDataSource(tableNum(VendPaymModeTable));

        tableQBDS.addSelectionField(fieldNum(VendPaymModeTable, PaymMode));
        tableQBDS.addSelectionField(fieldNum(VendPaymModeTable, Name));
        tableQBDS.addOrderByField(fieldnum(VendPaymModeTable, PaymMode));
        
        SysLookupMultiSelectGrid::lookup(query,
                                         parmFormStringControl,
                                         parmFormStringControl,
                                         parmFormStringControl,
                                         conContainer);
    }
